import app from 'flarum/common/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Tooltip from 'flarum/common/components/Tooltip';
import { buttonsFor, DEFAULT_TOOLBAR } from '../toolbarButtons';
/** Colours offered by the swatch row. Deliberately few — a forum post is not a design tool. */
const SWATCHES = ['#d83e3e', '#e8590c', '#f08c00', '#2f9e44', '#1971c2', '#6741d9', '#868e96'];
export default class ScribeToolbar extends Component {
  prompt = null;
  value = '';
  view() {
    const editor = this.attrs.editor;
    if (!editor) return null;
    const configured = app.forum.attribute('scribeToolbar') ?? DEFAULT_TOOLBAR;
    return m("div", {
      className: "Scribe-toolbarWrap"
    }, m("div", {
      className: "Scribe-toolbar",
      role: "toolbar",
      "aria-label": app.translator.trans('ernestdefoe-scribe.forum.composer.toolbar_label')
    }, buttonsFor(configured).map(b => this.button(b, editor))), this.prompt && this.promptRow(editor));
  }
  button(b, editor) {
    const label = app.translator.trans(`ernestdefoe-scribe.lib.buttons.${b.label}`);
    const active = b.active?.(editor) ?? false;
    return m(Tooltip, {
      text: label
    }, Button.component({
      className: 'Button Button--icon Button--link Scribe-toolbarButton' + (active ? ' is-active' : ''),
      icon: b.icon,
      // The pressed state is what tells a screen-reader user the cursor is
      // inside bold text, which sighted users read off the highlight.
      'aria-pressed': active ? 'true' : 'false',
      'aria-label': label,
      'data-badge': b.badge,
      disabled: b.enabled ? !b.enabled(editor) : false,
      onclick: () => {
        if (b.prompt) {
          this.openPrompt(b.prompt, editor);
        } else {
          b.run?.(editor);
        }
        this.attrs.onChange();
      }
    }));
  }
  openPrompt(kind, editor) {
    // Reopening the same prompt closes it, so the button toggles.
    this.prompt = this.prompt === kind ? null : kind;
    this.value = kind === 'link' ? editor.getAttributes('link').href ?? '' : '';
  }

  /**
   * 🚨 These three buttons open a form instead of toggling, and until this
   * existed they were wired to a no-op — present, labelled, styled, and doing
   * nothing. A control that looks like a feature and silently does nothing is
   * worse than one that is missing.
   */
  promptRow(editor) {
    const kind = this.prompt;
    const close = () => {
      this.prompt = null;
      this.value = '';
      editor.commands.focus();
      this.attrs.onChange();
    };
    if (kind === 'color') {
      return m("div", {
        className: "Scribe-prompt Scribe-prompt--color"
      }, SWATCHES.map(c => m("button", {
        type: "button",
        className: "Scribe-swatch",
        style: {
          background: c
        },
        "aria-label": c,
        title: c,
        onclick: () => {
          editor.chain().focus().setMark('scribeColor', {
            color: c
          }).run();
          close();
        }
      })), Button.component({
        className: 'Button Button--link Scribe-promptClear',
        onclick: () => {
          editor.chain().focus().unsetMark('scribeColor').run();
          close();
        }
      }, app.translator.trans('ernestdefoe-scribe.forum.composer.clear_colour')));
    }
    const placeholder = app.translator.trans(`ernestdefoe-scribe.forum.composer.${kind === 'link' ? 'link_placeholder' : 'image_placeholder'}`);
    const apply = () => {
      const url = this.value.trim();
      if (!url) return close();
      if (kind === 'link') {
        editor.chain().focus().extendMarkRange('link').setLink({
          href: url
        }).run();
      } else {
        editor.chain().focus().setImage({
          src: url
        }).run();
      }
      close();
    };
    return m("div", {
      className: "Scribe-prompt"
    }, m("input", {
      className: "FormControl Scribe-promptInput",
      type: "url",
      placeholder: placeholder,
      value: this.value,
      oninput: e => {
        this.value = e.target.value;
      },
      onkeydown: e => {
        if (e.key === 'Enter') {
          e.preventDefault();
          apply();
        } else if (e.key === 'Escape') {
          close();
        }
      },
      oncreate: v => v.dom.focus()
    }), Button.component({
      className: 'Button Button--primary Scribe-promptApply',
      onclick: apply
    }, app.translator.trans('ernestdefoe-scribe.forum.composer.apply')), kind === 'link' && editor.isActive('link') && Button.component({
      className: 'Button Button--link',
      onclick: () => {
        editor.chain().focus().extendMarkRange('link').unsetLink().run();
        close();
      }
    }, app.translator.trans('ernestdefoe-scribe.forum.composer.remove_link')));
  }
}
flarum.reg.add('ernestdefoe-scribe', 'common/components/ScribeToolbar', ScribeToolbar);